package audit

import (
	"errors"
	"fmt"
	"strings"
)

// Checker holds a map that maps event pairs to a dummy struct. It is basically
// used as a set to check for existence.
type Checker struct {
	eventActions map[string]struct{}
}

// NewChecker is the constructor for a Checker.
func NewChecker(eventPairs []string) (*Checker, error) {
	nouns := map[string][]string{
		"constraint":   {"constraint"},
		"distribution": {"distribution"},
		"flag":         {"flag"},
		"namespace":    {"namespace"},
		"rollout":      {"rollout"},
		"rule":         {"rule"},
		"segment":      {"segment"},
		"variant":      {"variant"},
		"*":            {"constraint", "distribution", "flag", "namespace", "rollout", "rule", "segment", "variant"},
	}

	verbs := map[string][]string{
		"created": {"created"},
		"deleted": {"deleted"},
		"updated": {"updated"},
		"*":       {"created", "deleted", "updated"},
	}

	eventActions := make(map[string]struct{})
	for _, ep := range eventPairs {
		epSplit := strings.Split(ep, ":")
		if len(epSplit) < 2 {
			return nil, fmt.Errorf("invalid event pair: %s", ep)
		}

		eventNouns, ok := nouns[epSplit[0]]
		if !ok {
			return nil, fmt.Errorf("invalid noun: %s", epSplit[0])
		}

		eventVerbs, ok := verbs[epSplit[1]]
		if !ok {
			return nil, fmt.Errorf("invalid verb: %s", epSplit[1])
		}

		for _, en := range eventNouns {
			for _, ev := range eventVerbs {
				eventPair := fmt.Sprintf("%s:%s", en, ev)

				_, ok := eventActions[eventPair]
				if ok {
					return nil, fmt.Errorf("repeated event pair: %s", eventPair)
				}

				eventActions[eventPair] = struct{}{}
			}
		}
	}

	if len(eventActions) == 0 {
		return nil, errors.New("no event pairs exist")
	}

	return &Checker{
		eventActions: eventActions,
	}, nil
}

// Check checks if an event pair exists in the Checker data structure for event emission.
func (c *Checker) Check(eventPair string) bool {
	_, ok := c.eventActions[eventPair]
	return ok
}

// Events returns the type of events we would like to emit to configured sinks.
func (c *Checker) Events() []string {
	var events = make([]string, 0, len(c.eventActions))
	for k := range c.eventActions {
		events = append(events, k)
	}

	return events
}
package audit

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestChecker(t *testing.T) {
	testCases := []struct {
		name          string
		eventPairs    []string
		expectedError error
		pairs         map[string]bool
	}{
		{
			name:          "wild card for nouns",
			eventPairs:    []string{"*:created"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   true,
				"distribution:created": true,
				"flag:created":         true,
				"namespace:created":    true,
				"rollout:created":      true,
				"rule:created":         true,
				"segment:created":      true,
				"variant:created":      true,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         false,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         false,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "wild card for verbs",
			eventPairs:    []string{"flag:*"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   false,
				"distribution:created": false,
				"flag:created":         true,
				"namespace:created":    false,
				"rollout:created":      false,
				"rule:created":         false,
				"segment:created":      false,
				"variant:created":      false,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         true,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         true,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "single pair",
			eventPairs:    []string{"flag:created"},
			expectedError: nil,
			pairs: map[string]bool{
				"constraint:created":   false,
				"distribution:created": false,
				"flag:created":         true,
				"namespace:created":    false,
				"rollout:created":      false,
				"rule:created":         false,
				"segment:created":      false,
				"variant:created":      false,
				"constraint:deleted":   false,
				"distribution:deleted": false,
				"flag:deleted":         false,
				"namespace:deleted":    false,
				"rollout:deleted":      false,
				"rule:deleted":         false,
				"segment:deleted":      false,
				"variant:deleted":      false,
				"constraint:updated":   false,
				"distribution:updated": false,
				"flag:updated":         false,
				"namespace:updated":    false,
				"rollout:updated":      false,
				"rule:updated":         false,
				"segment:updated":      false,
				"variant:updated":      false,
			},
		},
		{
			name:          "error repeating event pairs",
			eventPairs:    []string{"*:created", "flag:created"},
			expectedError: fmt.Errorf("repeated event pair: %s", "flag:created"),
		},
	}

	for _, tc := range testCases {
		checker, err := NewChecker(tc.eventPairs)
		if tc.expectedError != nil {
			assert.EqualError(t, err, tc.expectedError.Error())
			continue
		}

		for k, v := range tc.pairs {
			actual := checker.Check(k)
			assert.Equal(t, v, actual)
		}
	}
}
# Audit Events

Audit Events are pieces of data that describe a particular thing that has happened in a system. At Flipt, we provide the functionality of processing and batching these audit events and an abstraction for sending these audit events to a sink.

If you have an idea of a sink that you would like to receive audit events on, there are certain steps you would need to take to contribute, which are detailed below.

## Filterable Audit Events

The ability to filter audit events was added in [v1.27.0](https://github.com/flipt-io/flipt/releases/tag/v1.27.0) of Flipt. The following audit events are currently filterable:

### Nouns

- `flag`
- `segment`
- `variant`
- `constraint`
- `rule`
- `distribution`
- `namespace`
- `rollout`

### Verbs

- `created`
- `updated`
- `deleted`

Any combination of the above nouns and verbs can be used to filter audit events. For example, `flag:created` would filter audit events for only `created` events for `flags`.

You may also use the `*` wildcard to filter on all nouns or verbs. For example, `*:created` would filter audit events for only `created` events for all nouns.

Similarly, `flag:*` would filter audit events for all verbs for `flags`.

Finally, `*:*` would filter audit events for all nouns and verbs which is the default behavior.

## Contributing

The abstraction that we provide for implementation of receiving these audit events to a sink is [this](https://github.com/flipt-io/flipt/blob/d252d6c1fdaecd6506bf413add9a9979a68c0bd7/internal/server/audit/audit.go#L130-L134).

```go
type Sink interface {
	SendAudits([]Event) error
	Close() error
	fmt.Stringer
}
```

For contributions of new sinks, you can follow this pattern:

- Create a folder for your new sink under the `audit` package with a meaningful name of your sink
- Provide the implementation to how to send audit events to your sink via the `SendAudits`
- Provide the implementation of closing resources/connections to your sink via the `Close` method (this will be called asynchronously to the `SendAudits` method so account for that in your implementation)
- Provide the variables for configuration just like [here](https://github.com/flipt-io/flipt/blob/d252d6c1fdaecd6506bf413add9a9979a68c0bd7/internal/config/audit.go#L52) for connection details to your sink
- Add a conditional to see if your sink is enabled [here](https://github.com/flipt-io/flipt/blob/d252d6c1fdaecd6506bf413add9a9979a68c0bd7/internal/cmd/grpc.go#L261)
- Write respective tests

:rocket: you should be good to go!

